mapper.select:
/* com.heeji.picket.repository.PostRepository.list */
SELECT  *
FROM    POST
WHERE   1 = 1
AND     TYPE = #{type}

/* com.heeji.picket.repository.PostRepository.info */
SELECT  *
FROM    POST
WHERE   1 = 1
AND     POST_ID = #{postId}

mapper.update:
/* com.heeji.picket.repository.PostRepository.update */
UPDATE POST
SET UPDATE_DATE = NOW()
,   UPDATE_ID = #{loginId}
,   TITLE = #{title}
,   CONTENT = #{content}

mapper.delete:
/* com.heeji.picket.repository.PostRepository.delete */
DELETE FROM POST
WHERE       1 = 1
AND         POST_ID = #{postId}
